create extension if not exists pgcrypto;
create type public.member_role as enum ('owner','editor','viewer');
create type public.run_status as enum ('queued','running','paused','completed','failed');
create type public.step_status as enum ('pending','running','paused','completed','failed');
create table public.organizations (id uuid primary key default gen_random_uuid(), name text not null, calls_used integer not null default 0, calls_allowed integer not null default 500, period_start timestamptz not null default date_trunc('month', now()), created_at timestamptz not null default now());
create table public.org_members (org_id uuid references public.organizations on delete cascade, user_id uuid not null, role public.member_role not null, primary key(org_id,user_id));
create table public.workflows (id uuid primary key default gen_random_uuid(), org_id uuid not null references public.organizations on delete cascade, name text not null, created_by uuid not null, created_at timestamptz not null default now(), updated_at timestamptz not null default now());
create table public.workflow_steps (id uuid primary key default gen_random_uuid(), workflow_id uuid not null references public.workflows on delete cascade, position integer not null, type text not null check(type in ('llm_call','http_request','db_write','notify','conditional_branch','approval_gate')), config jsonb not null default '{}'::jsonb, unique(workflow_id,position));
create table public.workflow_triggers (id uuid primary key default gen_random_uuid(), workflow_id uuid not null references public.workflows on delete cascade, type text not null check(type in ('manual','webhook','scheduled','database_event')), config jsonb not null default '{}'::jsonb);
create table public.workflow_runs (id uuid primary key default gen_random_uuid(), workflow_id uuid not null references public.workflows on delete cascade, status public.run_status not null default 'queued', trigger_type text not null, input jsonb not null default '{}'::jsonb, started_at timestamptz, completed_at timestamptz, error text);
create table public.step_runs (id uuid primary key default gen_random_uuid(), workflow_run_id uuid not null references public.workflow_runs on delete cascade, workflow_step_id uuid not null references public.workflow_steps, status public.step_status not null default 'pending', input jsonb, output jsonb, error text, attempts integer not null default 0, approved_by uuid, approved_at timestamptz, created_at timestamptz not null default now());
create index step_runs_live_idx on public.step_runs(workflow_run_id,created_at);
create view public.organization_usage as select o.id as org_id,o.name,o.calls_used,o.calls_allowed,coalesce(avg(extract(epoch from (r.completed_at-r.started_at))) filter(where r.completed_at is not null),0) as average_run_seconds from organizations o left join workflows w on w.org_id=o.id left join workflow_runs r on r.workflow_id=w.id group by o.id;
